import Foundation

/// The bundled catalogue file: UTF-8 text, one item per line, tab-separated.
///
/// The format is line-based on purpose. The generated file is committed, so a
/// data update shows up as a reviewable diff, and the app parses it with a
/// single pass over the bytes.
///
/// ```text
/// # comment
/// !unicode<TAB>18.0.0                          header: key, value
/// 2192<TAB>s<TAB>0<TAB>1.1<TAB>Arrows<TAB>right arrow<TAB>rightwards arrow|east<TAB>->#0|arrow#0
/// @<TAB>4E00<TAB>9FFF<TAB>hex<TAB>CJK UNIFIED IDEOGRAPH-<TAB>CJK Unified Ideographs<TAB>1.1
/// ```
///
/// Entry fields: scalars (hex, space-separated), kind letter, rank, age,
/// group, name, keywords, aliases. Keywords and aliases are `|`-separated;
/// an alias may carry `#rank`. A `v` (variant) entry belongs to the nearest
/// preceding `e` (emoji) entry.
public enum CatalogFormat {
    public static let version = 1

    public struct Header: Sendable, Equatable {
        public var formatVersion: Int
        public var unicodeVersion: String
        public var emojiVersion: String
        public var cldrVersion: String

        public init(formatVersion: Int = CatalogFormat.version, unicodeVersion: String, emojiVersion: String, cldrVersion: String) {
            self.formatVersion = formatVersion
            self.unicodeVersion = unicodeVersion
            self.emojiVersion = emojiVersion
            self.cldrVersion = cldrVersion
        }
    }

    public struct Contents: Sendable, Equatable {
        public var header: Header
        public var entries: [CatalogEntry]
        public var ranges: [CodePointRange]

        public init(header: Header, entries: [CatalogEntry], ranges: [CodePointRange]) {
            self.header = header
            self.entries = entries
            self.ranges = ranges
        }
    }

    public enum FormatError: Error, Equatable, CustomStringConvertible {
        case unsupportedVersion(Int)
        case missingHeader(String)
        case malformedLine(number: Int, reason: String)
        case unencodableField(String)

        public var description: String {
            switch self {
            case .unsupportedVersion(let version):
                return "catalogue format \(version) is not supported (expected \(CatalogFormat.version))"
            case .missingHeader(let key):
                return "catalogue header '\(key)' is missing"
            case .malformedLine(let number, let reason):
                return "catalogue line \(number): \(reason)"
            case .unencodableField(let field):
                return "field contains a tab or newline and cannot be encoded: \(field)"
            }
        }
    }

    // MARK: - Kind letters

    static func letter(for kind: CatalogEntry.Kind) -> String {
        switch kind {
        case .emoji: return "e"
        case .variant: return "v"
        case .symbol: return "s"
        case .punctuation: return "p"
        case .letter: return "l"
        case .number: return "n"
        case .mark: return "m"
        case .space: return "z"
        }
    }

    static func kind(for letter: UInt8) -> CatalogEntry.Kind? {
        switch letter {
        case UInt8(ascii: "e"): return .emoji
        case UInt8(ascii: "v"): return .variant
        case UInt8(ascii: "s"): return .symbol
        case UInt8(ascii: "p"): return .punctuation
        case UInt8(ascii: "l"): return .letter
        case UInt8(ascii: "n"): return .number
        case UInt8(ascii: "m"): return .mark
        case UInt8(ascii: "z"): return .space
        default: return nil
        }
    }

    // MARK: - Encoding

    /// Serialises the catalogue deterministically: the same input always
    /// yields the same bytes.
    public static func encode(_ contents: Contents) throws -> String {
        var out = "# Charms catalogue. Generated by CharmsCatalogTool; do not edit by hand.\n"
        out += "!format\t\(contents.header.formatVersion)\n"
        out += "!unicode\t\(try plain(contents.header.unicodeVersion))\n"
        out += "!emoji\t\(try plain(contents.header.emojiVersion))\n"
        out += "!cldr\t\(try plain(contents.header.cldrVersion))\n"
        for entry in contents.entries {
            let scalars = entry.string.unicodeScalars.map { CodePoint.hex($0.value) }.joined(separator: " ")
            let keywords = try entry.keywords.map { try escapeListItem($0) }.joined(separator: "|")
            let aliases = try entry.aliases.map { alias -> String in
                let text = try escapeListItem(alias.text)
                return alias.rank == 0 ? text : "\(text)#\(alias.rank)"
            }.joined(separator: "|")
            out += scalars
            out += "\t\(letter(for: entry.kind))\t\(entry.rank)\t\(entry.age)\t"
            out += try plain(entry.group)
            out += "\t"
            out += try plain(entry.name)
            out += "\t\(keywords)\t\(aliases)\n"
        }
        for range in contents.ranges {
            let rule: String
            let prefix: String
            switch range.rule {
            case .hexSuffix(let value):
                rule = "hex"
                prefix = try plain(value)
            case .hangulSyllable:
                rule = "hangul"
                prefix = ""
            }
            out += "@\t\(CodePoint.hex(range.first))\t\(CodePoint.hex(range.last))\t\(rule)\t\(prefix)\t"
            out += try plain(range.group)
            out += "\t\(range.age)\n"
        }
        return out
    }

    private static func plain(_ field: String) throws -> String {
        if field.contains(where: { $0 == "\t" || $0.isNewline }) {
            throw FormatError.unencodableField(field)
        }
        return field
    }

    static func escapeListItem(_ item: String) throws -> String {
        _ = try plain(item)
        var out = ""
        out.reserveCapacity(item.utf8.count)
        for character in item {
            switch character {
            case "\\": out += "\\\\"
            case "|": out += "\\p"
            case "#": out += "\\h"
            default: out.append(character)
            }
        }
        return out
    }

    // MARK: - Decoding

    public static func decode(_ data: Data) throws -> Contents {
        var headers: [String: String] = [:]
        var entries: [CatalogEntry] = []
        var ranges: [CodePointRange] = []
        entries.reserveCapacity(data.count / 64)

        try data.withUnsafeBytes { (raw: UnsafeRawBufferPointer) in
            let bytes = raw.bindMemory(to: UInt8.self)
            var lineStart = 0
            var lineNumber = 0
            let count = bytes.count
            while lineStart < count {
                var lineEnd = lineStart
                while lineEnd < count, bytes[lineEnd] != UInt8(ascii: "\n") {
                    lineEnd += 1
                }
                lineNumber += 1
                let line = UnsafeBufferPointer(rebasing: bytes[lineStart..<lineEnd])
                lineStart = lineEnd + 1
                guard let first = line.first else { continue }
                switch first {
                case UInt8(ascii: "#"):
                    continue
                case UInt8(ascii: "!"):
                    let fields = split(line, separator: UInt8(ascii: "\t"))
                    guard fields.count == 2 else {
                        throw FormatError.malformedLine(number: lineNumber, reason: "header needs a key and a value")
                    }
                    headers[String(text(fields[0]).dropFirst())] = text(fields[1])
                case UInt8(ascii: "@"):
                    ranges.append(try decodeRange(line, lineNumber: lineNumber))
                default:
                    entries.append(try decodeEntry(line, lineNumber: lineNumber))
                }
            }
        }

        guard let formatText = headers["format"], let format = Int(formatText) else {
            throw FormatError.missingHeader("format")
        }
        guard format == version else {
            throw FormatError.unsupportedVersion(format)
        }
        guard let unicode = headers["unicode"] else { throw FormatError.missingHeader("unicode") }
        guard let emoji = headers["emoji"] else { throw FormatError.missingHeader("emoji") }
        guard let cldr = headers["cldr"] else { throw FormatError.missingHeader("cldr") }
        let header = Header(formatVersion: format, unicodeVersion: unicode, emojiVersion: emoji, cldrVersion: cldr)
        return Contents(header: header, entries: entries, ranges: ranges)
    }

    private typealias Bytes = UnsafeBufferPointer<UInt8>

    private static func split(_ line: Bytes, separator: UInt8) -> [Bytes] {
        var fields: [Bytes] = []
        fields.reserveCapacity(8)
        var start = 0
        for index in 0..<line.count where line[index] == separator {
            fields.append(Bytes(rebasing: line[start..<index]))
            start = index + 1
        }
        fields.append(Bytes(rebasing: line[start..<line.count]))
        return fields
    }

    private static func text(_ bytes: Bytes) -> String {
        String(decoding: bytes, as: UTF8.self)
    }

    private static func decodeEntry(_ line: Bytes, lineNumber: Int) throws -> CatalogEntry {
        let fields = split(line, separator: UInt8(ascii: "\t"))
        guard fields.count == 8 else {
            throw FormatError.malformedLine(number: lineNumber, reason: "expected 8 fields, found \(fields.count)")
        }
        guard let string = decodeScalars(fields[0]) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid scalar list")
        }
        guard fields[1].count == 1, let kind = kind(for: fields[1][0]) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "unknown kind")
        }
        guard let rank = UInt8(text(fields[2])) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid rank")
        }
        guard let age = UnicodeAge(text(fields[3])) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid age")
        }
        let aliases = try decodeList(fields[7]).map { item -> CatalogAlias in
            try decodeAlias(item, lineNumber: lineNumber)
        }
        return CatalogEntry(
            string: string,
            kind: kind,
            rank: rank,
            age: age,
            group: text(fields[4]),
            name: text(fields[5]),
            keywords: decodeList(fields[6]).map { unescapeListItem($0) },
            aliases: aliases
        )
    }

    private static func decodeRange(_ line: Bytes, lineNumber: Int) throws -> CodePointRange {
        let fields = split(line, separator: UInt8(ascii: "\t"))
        guard fields.count == 7 else {
            throw FormatError.malformedLine(number: lineNumber, reason: "expected 7 range fields, found \(fields.count)")
        }
        guard let first = UInt32(text(fields[1]), radix: 16), let last = UInt32(text(fields[2]), radix: 16), first <= last else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid range bounds")
        }
        let rule: CodePointRange.NameRule
        switch text(fields[3]) {
        case "hex": rule = .hexSuffix(prefix: text(fields[4]))
        case "hangul": rule = .hangulSyllable
        default: throw FormatError.malformedLine(number: lineNumber, reason: "unknown range rule")
        }
        guard let age = UnicodeAge(text(fields[6])) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid age")
        }
        return CodePointRange(first: first, last: last, rule: rule, group: text(fields[5]), age: age)
    }

    private static func decodeScalars(_ bytes: Bytes) -> String? {
        var scalars = String.UnicodeScalarView()
        var value: UInt32 = 0
        var digits = 0
        func flush() -> Bool {
            guard digits > 0, let scalar = Unicode.Scalar(value) else { return false }
            scalars.append(scalar)
            return true
        }
        for byte in bytes {
            if byte == UInt8(ascii: " ") {
                guard flush() else { return nil }
                value = 0
                digits = 0
                continue
            }
            let digit: UInt32
            switch byte {
            case UInt8(ascii: "0")...UInt8(ascii: "9"): digit = UInt32(byte - UInt8(ascii: "0"))
            case UInt8(ascii: "A")...UInt8(ascii: "F"): digit = UInt32(byte - UInt8(ascii: "A") + 10)
            case UInt8(ascii: "a")...UInt8(ascii: "f"): digit = UInt32(byte - UInt8(ascii: "a") + 10)
            default: return nil
            }
            guard digits < 6 else { return nil }
            value = value << 4 | digit
            digits += 1
        }
        guard flush() else { return nil }
        return String(scalars)
    }

    /// Splits on unescaped `|`. An empty field is an empty list.
    private static func decodeList(_ bytes: Bytes) -> [String] {
        guard !bytes.isEmpty else { return [] }
        var items: [String] = []
        var start = 0
        var index = 0
        while index < bytes.count {
            if bytes[index] == UInt8(ascii: "\\") {
                index += 2
                continue
            }
            if bytes[index] == UInt8(ascii: "|") {
                items.append(text(Bytes(rebasing: bytes[start..<index])))
                start = index + 1
            }
            index += 1
        }
        items.append(text(Bytes(rebasing: bytes[start..<bytes.count])))
        return items
    }

    private static func decodeAlias(_ item: String, lineNumber: Int) throws -> CatalogAlias {
        // The rank suffix is the last unescaped `#`.
        var rankStart: String.Index?
        var index = item.startIndex
        while index < item.endIndex {
            if item[index] == "\\" {
                index = item.index(index, offsetBy: 2, limitedBy: item.endIndex) ?? item.endIndex
                continue
            }
            if item[index] == "#" {
                rankStart = index
            }
            index = item.index(after: index)
        }
        guard let rankStart else {
            return CatalogAlias(text: unescapeListItem(item), rank: 0)
        }
        guard let rank = UInt8(item[item.index(after: rankStart)...]) else {
            throw FormatError.malformedLine(number: lineNumber, reason: "invalid alias rank")
        }
        return CatalogAlias(text: unescapeListItem(String(item[..<rankStart])), rank: rank)
    }

    static func unescapeListItem(_ item: String) -> String {
        guard item.contains("\\") else { return item }
        var out = ""
        var escaped = false
        for character in item {
            if escaped {
                switch character {
                case "p": out.append("|")
                case "h": out.append("#")
                default: out.append(character)
                }
                escaped = false
            } else if character == "\\" {
                escaped = true
            } else {
                out.append(character)
            }
        }
        return out
    }
}
